 for(int i=0;i<m;++i){int a{},b{};if(std::fscanf(file,"%d%d",&a,&b)!=2)return 5;graph[a-1].push_back(b-1);}std::fclose(file);
 const auto saved=graph;const int reps=std::max(1,65536/std::max(1,n+m));std::uint64_t checksum{};
 const auto start=std::clock();std::atomic_signal_fence(std::memory_order_seq_cst);
 for(int r=0;r<reps;++r){const auto answer=TopologicalSortLexicographical(graph);for(int v:answer)checksum=checksum*31+std::uint64_t(v);checksum+=answer.size();}
