# Generates supplemental inputs and independent heapq/Kahn branch statistics; never measures time.
import argparse, random, json, pathlib, heapq, hashlib
p=argparse.ArgumentParser();p.add_argument('kind',choices=['sparse_random','dense_random','wide_partial_cycle']);p.add_argument('order',choices=['grouped','shuffled','reversed']);p.add_argument('output');p.add_argument('--seed',type=int,default=80490774);args=p.parse_args();rng=random.Random(args.seed)
n=1024 if args.kind=='dense_random' else 200000;m=200000;cycle=8192 if args.kind=='wide_partial_cycle' else 0;dag=n-cycle
labels=list(range(n));rng.shuffle(labels);edges=set()
while len(edges)<m-cycle:
 a,b=sorted(rng.sample(range(dag),2));edges.add((labels[a],labels[b]))
if cycle:
 for i in range(cycle):edges.add((labels[dag+i],labels[dag+(i+1)%cycle]))
edges=sorted(edges)
if args.order=='shuffled':rng.shuffle(edges)
elif args.order=='reversed':edges.reverse()
g=[[]for _ in range(n)];degree=[0]*n
for a,b in edges:g[a].append(b);degree[b]+=1
q=[i for i,d in enumerate(degree)if d==0];heapq.heapify(q);seen=[];remaining_ready=0;fallback=0;same_leaf=0;single=0;initial_roots=len(q)
while q:
 x=heapq.heappop(q);seen.append(x)
 if q:
  remaining_ready+=1
  if q[0]//64==x//64:same_leaf+=1
  else:fallback+=1
 else:single+=1
 for y in g[x]:
  degree[y]-=1
  if degree[y]==0:heapq.heappush(q,y)
text=f'{n} {len(edges)}\n'+''.join(f'{a+1} {b+1}\n'for a,b in edges);path=pathlib.Path(args.output);path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text);expected=' '.join(str(x+1)for x in seen)+'\n'if len(seen)==n else '-1\n';path.with_suffix('.expected').write_text(expected)
metadata=dict(kind=args.kind,edge_order=args.order,seed=args.seed,n=n,m=len(edges),distinct_edges=True,self_loops=False,declared_abc223_bounds=True,initial_ready=initial_roots,processed_vertices=len(seen),vertices_in_cycle_component=cycle,nonempty_after_cached_pop=remaining_ready,same_leaf_searches=same_leaf,root_searches=fallback,no_remaining_after_cached_pop=single,input_sha256=hashlib.sha256(text.encode()).hexdigest(),stdout_sha256=hashlib.sha256(expected.encode()).hexdigest(),performance_measured=False)
path.with_suffix('.json').write_text(json.dumps(metadata,indent=2));print(json.dumps(metadata))

